   Dashboard Custom CSS: no length limit, so this is the section and theme blocks merged,
   plus the two rules that did not fit in Shopify. */

/* Band, edge to edge. The negative margins cancel `.section{padding:1.5em 0 2.5em}` in the
   theme's own styles.css, which the editor's Section padding control does not reach. */
#gigit-shop-concierge {
  width: 100vw;
  margin: -1.5em 0 -2.5em calc(50% - 50vw);
  font-family: "DM Sans", sans-serif !important;
  --i: #252424;
  --q: #efe9e0;
  --l: #7a736a;
}
#gigit-shop-concierge .tw-p-\[20px\] {
  padding: clamp(40px, 4vw, 60px) clamp(20px, 6vw, 87px) 24px !important;
}
#gigit-shop-concierge .tw-text-\[24px\] {
  font: 500 clamp(20px, 2.5vw, 32px)/1.1 "Tomato Grotesk", sans-serif !important;
}

/* Search bar, matching .hgg-conc__form: square, 1px box, button flush right. The shimmer
   frame and the star both go; the frame keeps a 24px radius of its own. */
#gigit-shop-concierge form { border: 1px solid #000; }
#gigit-shop-concierge form > div:first-child,
#gigit-shop-concierge form > div:nth-child(3) { display: none !important; }
#gigit-shop-concierge form input {
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  padding-left: 16px !important;
}
#gigit-shop-concierge form button {
  border-radius: 0 !important;
  inset: 0 0 0 auto !important;
  height: auto !important;
  transform: none !important;
}
#gigit-shop-concierge .tw-flex-wrap > button { border-radius: 0 !important; }

/* Chat. STOPGAP on the next line: ChatHistory.tsx:50 writes `flex flex-col` unprefixed
   while the build uses `tw-`, so nothing defines .flex-col and the thread lays out
   sideways. Delete it once that is fixed in code. */
#gigit-shop-concierge .flex.flex-col { flex-direction: column !important; }

#gigit-shop-concierge [data-gigit-message^=u] {
  justify-content: flex-end;
  padding: 0;
  margin: 0 0 20px;
}
#gigit-shop-concierge [data-gigit-message^=u] > div:last-child {
  width: fit-content;
  max-width: 82%;
  padding: 12px 16px;
  background: var(--q);
  border-radius: 18px 18px 4px 18px;
  color: var(--i) !important;
  overflow-wrap: anywhere;
}
#gigit-shop-concierge [data-gigit-message^=u] > div:first-child { order: 1; }
#gigit-shop-concierge [data-gigit-message^=u] img {
  background: #fffffc !important;
  border: 1px solid var(--i);
  box-sizing: border-box;
}

#gigit-shop-concierge [data-gigit-message^=a] {
  gap: 12px;
  padding: 0;
  margin: 0 0 14px;
}
#gigit-shop-concierge [data-gigit-message^=a] p {
  width: 100% !important;
  margin: 4px 0 0;
  font-size: 15px;
  line-height: 1.7;
  overflow-wrap: anywhere;
}
/* OldAIMessage sets a height in JavaScript from 20px lines; let CSS measure the text. */
#gigit-shop-concierge [data-gigit-message^=a] > div:last-child {
  height: auto !important;
  min-height: 28px;
  min-width: 0;
  max-width: none;
  color: var(--i) !important;
}

#gigit-shop-concierge [data-gigit-message] > div:first-child,
#gigit-shop-concierge [data-gigit-message] > div:first-child > :is(span, img) {
  width: 28px;
  height: 28px;
  border-radius: 50%;
}

/* Back in, now that there is room: the small-caps speaker labels, and the feedback row
   pulled in to the 28px avatar from the 64px it assumes. */
#gigit-shop-concierge [data-gigit-message^=u] > div:last-child > div:first-child,
#gigit-shop-concierge [data-gigit-message^=a] .tw-font-semibold {
  font-family: "Tomato Grotesk", sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--l);
}
#gigit-shop-concierge [data-gigit-message^=a] ~ .tw-pl-\[64px\] { padding-left: 40px; }
#gigit-shop-concierge button[aria-label^="Thumbs"] { border: 0 !important; }

/* Gigit Shop Concierge — make the product row read as part of the reply. */

/* 1. The cream runs behind the product row, not just behind the chat, so there
      is no white cut line between the input and the cards. */
#gigit-shop-concierge > div:first-child,
#gigit-shop-concierge .tw-rounded-\[10px\].tw-py-\[3px\] {
    background-color: #faf7f1 !important;
}

/* 2. White image tile. The card's tile is the same cream as the band, so on a
      cream ground it loses its only edge. !important is required here: the
      colour arrives as an inline style attribute. */
#gigit-shop-concierge .tw-grid.tw-grid-cols-2 .tw-relative.tw-overflow-hidden {
    background-color: #ffffff !important;
}

/* 3. Phone: one swipeable line of full-size cards instead of a 2x2 block.
      No JavaScript — scroll-snap does the paging. */
#gigit-shop-concierge .tw-grid.tw-grid-cols-2 {
    display: flex !important;
    gap: 12px !important;
    max-width: none !important;
    padding: 0 20px !important;
    justify-content: flex-start !important;
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: none;
}
#gigit-shop-concierge .tw-grid.tw-grid-cols-2 > * {
    flex: 0 0 68% !important;
    scroll-snap-align: start;
}
#gigit-shop-concierge .tw-grid.tw-grid-cols-2::-webkit-scrollbar {
    display: none;
}

/* 4. Desktop: the chat widens to the product row's own measure, so the two
      share one width instead of the row overhanging by ~200px each side.
      4 cards x 235px + 3 gaps x 20px = 1000px exactly. Fixed card widths keep
      a 2- or 3-product reply looking deliberate rather than half-empty. */
@media (min-width: 768px) {
    #gigit-shop-concierge .tw-max-w-\[600px\] {
        max-width: 1000px !important;
    }
    #gigit-shop-concierge .tw-grid.tw-grid-cols-2 {
        gap: 20px !important;
        justify-content: center !important;
        overflow-x: visible;
        scroll-snap-type: none;
    }
    #gigit-shop-concierge .tw-grid.tw-grid-cols-2 > * {
        flex: 0 0 235px !important;
    }
}

